/* The Legend of Zelda set additions — cards appended after zelda.js.
   (zelda.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'zelda.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('zelda');
  if (!S) return;
  var extra = [{"name":"Ganon","rarity":"legendary","id":"ganon","subtitle":"Boss","details":"The Demon King's true beast form, a hulking boar wreathed in malice who wields a trident as the final trial awaiting hero after hero.","image":"assets/sets/compress/zelda-additions__ganon.webp"},{"name":"Demise","rarity":"legendary","id":"demise","subtitle":"Boss","details":"The original Demon King, a towering figure of fire and darkness whose dying curse binds his hatred to the hero and the goddess forever.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/a5/SSHD_Demise_Model.png"},{"name":"Majora","rarity":"legendary","id":"majora","subtitle":"Boss","details":"The malevolent spirit inside an ancient mask, it twists its wearer into a puppet and drags the moon down toward Termina for sport.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/f/f5/MM3D_Majora%27s_Wrath_Model.png/320px-MM3D_Majora%27s_Wrath_Model.png"},{"name":"Calamity Ganon","rarity":"legendary","id":"calamity-ganon","subtitle":"Boss","details":"Pure malice given form, this swirling scourge shattered Hyrule a century before the hero awoke and seized the Divine Beasts from within.","image":"assets/sets/compress/zelda-additions__calamity-ganon.webp"},{"name":"Vaati's Wrath","rarity":"legendary","id":"vaatis-wrath","subtitle":"Boss","details":"The wind sorcerer's final shape, a towering mass of clawed limbs and glaring eyes fought above the palace roof in a storm of curses.","image":"https://www.zeldadungeon.net/wiki/images/1/1c/VaatisWrath1.gif"},{"name":"Twinrova","rarity":"legendary","id":"twinrova","subtitle":"Boss","details":"Sisters Koume and Kotake, flame and ice witches who raised Ganondorf, merge into the beautiful and deadly Twinrova when cornered together.","image":"https://www.zeldadungeon.net/wiki/images/a/a4/Twinrova_merged_-_OOT64.jpg"},{"name":"Malladus","rarity":"epic","id":"malladus","subtitle":"Boss","details":"An ancient Demon King whose disembodied spirit is chained beneath the Tower of Spirits, scheming to steal a vessel worthy of his power.","image":"https://cdn.wikimg.net/en/zeldawiki/images/b/b0/ST_Malladus_Model_3.png"},{"name":"Bellum","rarity":"epic","id":"bellum","subtitle":"Boss","details":"A squid-like phantom from the depths that feeds on life force, it curses the Ocean King and slowly drains the seas of their guardian.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c0/PH_Bellum_Artwork.png/320px-PH_Bellum_Artwork.png"},{"name":"Phantom Ganon","rarity":"epic","id":"phantom-ganon","subtitle":"Boss","details":"A spectral puppet of Ganondorf armed with a trident and dark orbs, it haunts the Forest Temple and the Forsaken Fortress alike.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/8a/OoT_Phantom_Ganon_Artwork.png/512px-OoT_Phantom_Ganon_Artwork.png"},{"name":"Dark Link","rarity":"epic","id":"dark-link","subtitle":"Boss","details":"A silent shadow born from reflection and dark magic, it mimics every sword stroke in a duel where the hero fights himself.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/14/OoT3D_Dark_Link_Model.png"},{"name":"Stallord","rarity":"epic","id":"stallord","subtitle":"Boss","details":"A gigantic dragon fossil raised by dark twilight magic, it rides a sand arena spitting fire while its head survives its own body.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/4/4e/TP_Stallord_Render.png/320px-TP_Stallord_Render.png"},{"name":"Koloktos","rarity":"epic","id":"koloktos","subtitle":"Boss","details":"A six-armed golden automaton built to guard a sacred flame, it turns its own enormous blades against any thief who wakes it.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/87/SS_Koloktos_Render.png/320px-SS_Koloktos_Render.png"},{"name":"Lynel","rarity":"epic","id":"lynel","subtitle":"Enemy","details":"A centaur-like warrior of unmatched pride and power, it patrols its territory with savage weapons and charges down any challenger.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/bd/BotW_Lynel_Model.png/320px-BotW_Lynel_Model.png"},{"name":"Guardian","rarity":"epic","id":"guardian","subtitle":"Enemy","details":"Ancient Sheikah machines corrupted by malice, their single blue eye locks on with a beep before unleashing a devastating beam.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/9b/BotW_Guardian_Artwork.png/512px-BotW_Guardian_Artwork.png"},{"name":"Darknut","rarity":"rare","id":"darknut","subtitle":"Enemy","details":"Elite knights sealed in layered black armor; each plate stripped away makes them faster, lighter and far more aggressive duelists.","image":"assets/sets/compress/zelda-additions__darknut.webp"},{"name":"Iron Knuckle","rarity":"rare","id":"iron-knuckle","subtitle":"Enemy","details":"Towering axe-men in crushing plate armor, said to hide something stranger beneath the helmet in the Spirit Temple's dark halls.","image":"assets/sets/compress/zelda-additions__iron-knuckle.webp"},{"name":"Gohma","rarity":"rare","id":"gohma","subtitle":"Boss","details":"A giant one-eyed arachnid queen whose offspring swarm her chambers; only a strike to her glaring eye can bring the beast down.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/ee/OoT_Gohma_Artwork.png/512px-OoT_Gohma_Artwork.png"},{"name":"King Dodongo","rarity":"rare","id":"king-dodongo","subtitle":"Boss","details":"The infernal dinosaur ruling the cavern that bears its name, it seals the Gorons' food supply and breathes rolling walls of fire.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/10/OoT_King_Dodongo_Artwork.png/512px-OoT_King_Dodongo_Artwork.png"},{"name":"Volvagia","rarity":"rare","id":"volvagia","subtitle":"Boss","details":"A serpentine dragon of living lava that dives through molten pools in the Fire Temple, snapping at the hero between eruptions.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/74/OoT_Volvagia_Artwork.png/512px-OoT_Volvagia_Artwork.png"},{"name":"Bongo Bongo","rarity":"rare","id":"bongo-bongo","subtitle":"Boss","details":"A phantom sealed beneath the well, freed to drum its severed hands on a giant bongo while its single red eye hunts in the dark.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/ed/OoT_Bongo_Bongo_Artwork.png/512px-OoT_Bongo_Bongo_Artwork.png"},{"name":"Morpha","rarity":"rare","id":"morpha","subtitle":"Boss","details":"A giant amoeba nucleus that seizes control of the Water Temple itself, whipping long tentacles of water at anyone who wades in.","image":"assets/sets/compress/zelda-additions__morpha.webp"},{"name":"Helmaroc King","rarity":"rare","id":"helmaroc-king","subtitle":"Boss","details":"A colossal masked bird in Ganondorf's service, it snatches girls from across the Great Sea and drops intruders from great heights.","image":"assets/sets/compress/zelda-additions__helmaroc-king.webp"},{"name":"Puppet Ganon","rarity":"rare","id":"puppet-ganon","subtitle":"Boss","details":"A towering marionette worked by threads from the rafters, it shifts between boar, spider and serpent shapes in Ganon's tower.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/0/0a/TWW_Puppet_Ganon_Artwork.png/320px-TWW_Puppet_Ganon_Artwork.png"},{"name":"Argorok","rarity":"rare","id":"argorok","subtitle":"Boss","details":"A wyvern clad in iron plate that terrorizes the sky city, it must be dragged down by its own tail and fought among falling towers.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/6f/TP_Argorok_Render.png/320px-TP_Argorok_Render.png"},{"name":"Thunderblight Ganon","rarity":"rare","id":"thunderblight-ganon","subtitle":"Boss","details":"The fastest of the blights, a phantom of crackling electricity that darts around Vah Naboris in blinding zigzag strikes.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/54/BotW_Thunderblight_Ganon_Model.png"},{"name":"Queen Gibdo","rarity":"rare","id":"queen-gibdo","subtitle":"Boss","details":"The winged matriarch of the desert undead, her piercing shriek summons waves of Gibdo to defend the ruins beneath Gerudo Town.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/d7/TotK_Queen_Gibdo_Model.png/320px-TotK_Queen_Gibdo_Model.png"},{"name":"ReDead","rarity":"uncommon","id":"redead","subtitle":"Enemy","details":"Hollow-eyed corpses whose paralyzing scream roots the hero in place before they shuffle close and latch on with cold hands.","image":"assets/sets/compress/zelda-additions__redead.webp"},{"name":"Gibdo","rarity":"uncommon","id":"gibdo","subtitle":"Enemy","details":"Bandage-wrapped mummies of the deep places; fire strips their wrappings to reveal the shambling ReDead horror hidden underneath.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/70/OoT_Gibdo_Model.png"},{"name":"Like Like","rarity":"uncommon","id":"like-like","subtitle":"Enemy","details":"A rubbery tube of a creature that lunges, swallows the hero whole and spits him out minus a shield or a favorite tunic.","image":"https://cdn.wikimg.net/en/zeldawiki/images/0/01/OoT3D_Like_Like_Model.png"},{"name":"Wallmaster","rarity":"uncommon","id":"wallmaster","subtitle":"Enemy","details":"A giant hand that creeps across dungeon ceilings, watching for its shadow to fall before it snatches the hero back to the door.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/51/OoT_Wallmaster_Model.png"},{"name":"Wizzrobe","rarity":"uncommon","id":"wizzrobe","subtitle":"Enemy","details":"Hooded sorcerers who flicker from spot to spot in a swirl of magic, conjuring fire, ice storms and even enemies of their own.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/6e/ALttP_Wizzrobe_Artwork.png"},{"name":"Stalfos","rarity":"uncommon","id":"stalfos","subtitle":"Enemy","details":"The restless bones of fallen warriors, these sword-and-shield skeletons rise in crypts and duel with surprising skill.","image":"assets/sets/compress/zelda-additions__stalfos.webp"},{"name":"Poe","rarity":"uncommon","id":"poe","subtitle":"Enemy","details":"Lantern-bearing spirits of the dead that drift through graveyards and ruins, vanishing and reappearing to strike from behind.","image":"assets/sets/compress/zelda-additions__poe.webp"},{"name":"Beamos","rarity":"uncommon","id":"beamos","subtitle":"Enemy","details":"Ancient stone sentries topped with a rotating eye; the moment it glows red, a searing beam follows the hero across the room.","image":"assets/sets/compress/zelda-additions__beamos.webp"},{"name":"Lizalfos","rarity":"uncommon","id":"lizalfos","subtitle":"Enemy","details":"Chameleon-like lizard warriors that hop, dart and spit in pairs, their tails and tongues as quick as their curved blades.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/f/fd/BotW_Lizalfos_Model.png/320px-BotW_Lizalfos_Model.png"},{"name":"Hinox","rarity":"uncommon","id":"hinox","subtitle":"Enemy","details":"A one-eyed giant that sleeps in the wild, then wakes to rip up trees and hurl bomb barrels with earth-shaking strength.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c8/TotK_Hinox_Model.png/320px-TotK_Hinox_Model.png"},{"name":"Molduga","rarity":"uncommon","id":"molduga","subtitle":"Enemy","details":"A colossal fish of the sand sea that hunts by vibration, breaching high into the air to swallow whatever disturbs the dunes.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/a1/BotW_Molduga_Model.png"},{"name":"Stone Talus","rarity":"uncommon","id":"stone-talus","subtitle":"Enemy","details":"A mountain that wakes: living rock assembles into a hulking giant whose ore heart sits high on its back, begging to be climbed.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/5/59/TotK_Stone_Talus_Model.png/320px-TotK_Stone_Talus_Model.png"},{"name":"Armos","rarity":"uncommon","id":"armos","subtitle":"Enemy","details":"Carved guardian statues that shudder to life when touched, hopping heavily after intruders in temples and mountain passes.","image":"assets/sets/compress/zelda-additions__armos.webp"},{"name":"Dead Hand","rarity":"uncommon","id":"dead-hand","subtitle":"Enemy","details":"A nightmare of the Bottom of the Well: pale hands pin the hero while a bloated, long-necked horror rises to take a bite.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/90/OoT3D_Dead_Hand_Model.png"},{"name":"Molgera","rarity":"uncommon","id":"molgera","subtitle":"Boss","details":"Guardian of the Wind Temple and a larva of the deep sand, this colossal worm bursts upward with jaws wide and tongue exposed.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/3/38/TWW_Molgera_Artwork.png/320px-TWW_Molgera_Artwork.png"},{"name":"Aquamentus","rarity":"uncommon","id":"aquamentus","subtitle":"Boss","details":"A horned, fire-breathing dragon standing guard over the first shard of the Triforce, the very first boss a hero ever faced.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/bb/TLoZ_Aquamentus_Artwork.png/320px-TLoZ_Aquamentus_Artwork.png"},{"name":"Jalhalla","rarity":"uncommon","id":"jalhalla","subtitle":"Boss","details":"The giant of the Earth Temple's Poes, a masked phantom that scatters into a giggling swarm when caught in a beam of light.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/b3/TWW_Jalhalla_Artwork.png/320px-TWW_Jalhalla_Artwork.png"},{"name":"Frox","rarity":"uncommon","id":"frox","subtitle":"Enemy","details":"A mountain-sized frog of the Depths with a cavernous mouth, it inhales everything nearby and hides ore across its broad back.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/1c/TotK_Frox_Model.png/320px-TotK_Frox_Model.png"},{"name":"Bokoblin","rarity":"common","id":"bokoblin","subtitle":"Enemy","details":"The pig-snouted foot soldier of monster camps everywhere, fond of clubs, campfires and food stolen from passing travelers.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/c5/BotW_Bokoblin_Model.png"},{"name":"Moblin","rarity":"common","id":"moblin","subtitle":"Enemy","details":"A hulking brute in service to dark powers since the earliest quests, charging with spears, swords and surprising speed.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/86/BotW_Moblin_Model.png/320px-BotW_Moblin_Model.png"},{"name":"Octorok","rarity":"common","id":"octorok","subtitle":"Enemy","details":"A red river octopus that surfaces without warning to spit rocks; some of its kin hide in grass, snow and even lava flows.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/4/46/OoT_Octorok_Artwork.png/320px-OoT_Octorok_Artwork.png"},{"name":"Keese","rarity":"common","id":"keese","subtitle":"Enemy","details":"Leathery bats that pour from dark ceilings in fluttering swarms; elemental kin arrive wreathed in fire, ice or lightning.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/f6/OoT_Keese_Model.png"},{"name":"ChuChu","rarity":"common","id":"chuchu","subtitle":"Enemy","details":"A wobbling blob of living jelly that hops toward the hero; its colorful juices are prized for brewing all manner of potions.","image":"assets/sets/compress/zelda-additions__chuchu.webp"},{"name":"Tektite","rarity":"common","id":"tektite","subtitle":"Enemy","details":"A one-eyed, long-legged spider that skitters and leaps across hillsides, and in some lands skims straight over the water.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c2/OoT_Blue_Tektite_Artwork.png/320px-OoT_Blue_Tektite_Artwork.png"},{"name":"Deku Baba","rarity":"common","id":"deku-baba","subtitle":"Enemy","details":"A rooted piranha plant of the forest floor, lunging on a snapping stalk; its seeds and sticks are a young hero's first harvest.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/c6/OoT3D_Deku_Baba_Model.png"},{"name":"Skulltula","rarity":"common","id":"skulltula","subtitle":"Enemy","details":"A skull-shelled spider that dangles into dungeon paths on silk threads, guarding its soft underside behind a bony mask.","image":"assets/sets/compress/zelda-additions__skulltula.webp"},{"name":"Leever","rarity":"common","id":"leever","subtitle":"Enemy","details":"A spinning burrower that churns beneath desert sands, surfacing in a straight relentless line at anything crossing its dunes.","image":"assets/sets/compress/zelda-additions__leever.webp"},{"name":"Peahat","rarity":"common","id":"peahat","subtitle":"Enemy","details":"A propeller-bladed plant that uproots itself and sails through the air, its spinning leaves slicing at heroes below.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/d0/OoT3D_Peahat_Model.png/320px-OoT3D_Peahat_Model.png"},{"name":"Zol","rarity":"common","id":"zol","subtitle":"Enemy","details":"A green gel that oozes across dungeon floors and splits into two smaller Gels with every sword strike it survives.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/11/TLoZ_Zol_Artwork.png"},{"name":"Rope","rarity":"common","id":"rope","subtitle":"Enemy","details":"A dungeon snake that dozes in coiled stillness until the hero draws near, then strikes in one sudden, darting charge.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/7c/EoW_Rope_Model.png/320px-EoW_Rope_Model.png"},{"name":"Goriya","rarity":"common","id":"goriya","subtitle":"Enemy","details":"A rat-like boomerang thrower of the earliest dungeons, it keeps its distance and peppers the hero from across the room.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/72/TLoZ_Blue_Goriya_Artwork.png"},{"name":"Miniblin","rarity":"common","id":"miniblin","subtitle":"Enemy","details":"Tiny pitchfork imps that pour over the railings of sea fortresses in squeaking waves, jabbing at anything within reach.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/f7/TWW_Miniblin_Model.png"},{"name":"Bulblin","rarity":"common","id":"bulblin","subtitle":"Enemy","details":"Green-skinned raiders who ride armored Bullbos and raise the alarm at monster camps with a blast of their long horns.","image":"https://cdn.wikimg.net/en/zeldawiki/images/0/06/TP_Bulblin_Model.png"},{"name":"Wolfos","rarity":"common","id":"wolfos","subtitle":"Enemy","details":"A spectral-eyed wolf that circles just beyond sword range, lunging only when the hero turns his back or drops his guard.","image":"https://cdn.wikimg.net/en/zeldawiki/images/d/d1/OoT_Wolfos_Model.png"},{"name":"Bubble","rarity":"common","id":"bubble","subtitle":"Enemy","details":"A flaming skull that bounces erratically around dungeon rooms; its cursed fire can seal away the hero's sword entirely.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/22/OoT_Blue_Bubble_Artwork.png/320px-OoT_Blue_Bubble_Artwork.png"},{"name":"Pols Voice","rarity":"common","id":"pols-voice","subtitle":"Enemy","details":"A long-eared hopper of the first dungeons, strangely fragile before certain sounds that other heroes carry as weapons.","image":"https://cdn.wikimg.net/en/zeldawiki/images/3/39/TLoZ_Pols_Voice_Artwork.png"},{"name":"Stalchild","rarity":"common","id":"stalchild","subtitle":"Enemy","details":"A child-sized skeleton that claws out of Hyrule Field after dark, endlessly rising in twos and threes until sunrise.","image":"https://cdn.wikimg.net/en/zeldawiki/images/8/85/OoT_Stalchild_Model.png"},{"name":"Deku Scrub","rarity":"common","id":"deku-scrub","subtitle":"Enemy","details":"A shrub-headed forest dweller that pops from the grass spitting nuts, then happily trades secrets and goods once caught.","image":"assets/sets/compress/zelda-additions__deku-scrub.webp"},{"name":"Kargarok","rarity":"common","id":"kargarok","subtitle":"Enemy","details":"A huge, screeching seabird that shadows ships and sky islands alike, snatching at heroes with hooked talons mid-flight.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/ca/TP_Kargarok_Model.png"},{"name":"Guay","rarity":"common","id":"guay","subtitle":"Enemy","details":"A ragged crow that waits on perches and fence posts, then dives in a cawing spiral at any hero who wanders underneath.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/c0/OoT3D_Guay_Model.png"},{"name":"Rat","rarity":"common","id":"rat","subtitle":"Enemy","details":"A quick-fingered rodent of fortresses and towers that bumps into heroes in the dark and makes off with their Rupees.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/5a/TWW_Rat_Model.png"},{"name":"Moldorm","rarity":"common","id":"moldorm","subtitle":"Boss","details":"A huge segmented worm that races around its arena edge, knocking heroes into the pit; only its glowing tail can be hurt.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/1c/TLoZ_Moldorm_Artwork.png/320px-TLoZ_Moldorm_Artwork.png"},{"name":"Lanmola","rarity":"common","id":"lanmola","subtitle":"Boss","details":"A giant centipede that bursts from the desert floor in a spray of sand, circling the palace ruins before diving again.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/57/LANS_Lanmola_Model.png"},{"name":"Gleeok","rarity":"common","id":"gleeok","subtitle":"Boss","details":"A fire-breathing dragon whose many heads detach and swarm the hero; in the wilds it rules bridges and high lonely places.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/4/4b/TotK_Flame_Gleeok_Model.png/320px-TotK_Flame_Gleeok_Model.png"},{"name":"Master Sword","rarity":"chase","id":"master-sword","subtitle":"Sword","details":"Forged by the goddess Hylia and tempered in three sacred flames, this blade seals darkness and rests in its pedestal until a worthy hero draws it.","image":"https://cdn.wikimg.net/en/zeldawiki/images/8/89/BotW_Master_Sword_Model.png"},{"name":"Triforce","rarity":"chase","id":"triforce","subtitle":"Relic","details":"Left behind by Din, Nayru and Farore at creation, this golden relic grants any wish to the one who touches it with a balanced heart of its virtues.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/70/ALBW_Triforce_Artwork.png/320px-ALBW_Triforce_Artwork.png"},{"name":"Majora's Mask","rarity":"chase","id":"majoras-mask","subtitle":"Mask","details":"Carved from the arms of a legendary monster and used in ancient hexing rituals, this cursed mask slowly possesses its wearer and nearly drops a moon.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/ef/MM3D_Majora%27s_Mask_Render.png/320px-MM3D_Majora%27s_Mask_Render.png"},{"name":"Hylian Shield","rarity":"legendary","id":"hylian-shield","subtitle":"Shield","details":"Borne by Hyrule's knights and stamped with the royal crest, this metal shield withstands dragon fire and, in Hyrule's finest smithies, never breaks.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/4d/BotW_Hylian_Shield_Model.png"},{"name":"Fierce Deity Mask","rarity":"legendary","id":"fierce-deity-mask","subtitle":"Mask","details":"Earned only by trading away every other mask in Termina, this fearsome face turns its wearer into a towering, sword-beam-firing god of war in battle.","image":"assets/sets/compress/zelda-additions__fierce-deity-mask.webp"},{"name":"Four Sword","rarity":"legendary","id":"four-sword","subtitle":"Sword","details":"A Picori gift reforged in the four elements, this blade splits its wielder into four copies of himself to fight the wind mage Vaati side by side.","image":"https://cdn.wikimg.net/en/zeldawiki/images/e/e1/TMC_Four_Sword_Artwork.png"},{"name":"Ocarina of Time","rarity":"legendary","id":"ocarina-of-time","subtitle":"Instrument","details":"A blue ceramic ocarina kept by Hyrule's royal family, its melodies open the Door of Time and carry the player seven years into the past and future.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/97/OoT_Ocarina_of_Time_Render.png"},{"name":"Tri Rod","rarity":"legendary","id":"tri-rod","subtitle":"Rod","details":"Princess Zelda's wand in Echoes of Wisdom, gifted by the fairy Tri; it records objects and monsters so she can summon echoes of them at will anywhere.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/4a/EoW_Tri_Rod_Model.png"},{"name":"Mirror Shield","rarity":"epic","id":"mirror-shield","subtitle":"Shield","details":"Its polished face reflects sunlight to melt ice, petrify enemies, and turn Medusa-like traps back on themselves inside temples and desert ruins.","image":"assets/sets/compress/zelda-additions__mirror-shield.webp"},{"name":"Biggoron's Sword","rarity":"epic","id":"biggorons-sword","subtitle":"Sword","details":"Forged atop Death Mountain by the giant smith Biggoron, this two-handed blade out-damages the Master Sword but leaves both hands too full for a shield.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/fc/OoT_Biggoron%27s_Sword_Model.png"},{"name":"Goddess Sword","rarity":"epic","id":"goddess-sword","subtitle":"Sword","details":"Drawn from a statue of the goddess on Skyloft, this blade houses the spirit Fi, dowses for hidden targets, and is reforged into the Master Sword itself.","image":"https://cdn.wikimg.net/en/zeldawiki/images/8/8d/SS_Goddess_Sword_Model.png"},{"name":"Phantom Sword","rarity":"epic","id":"phantom-sword","subtitle":"Sword","details":"Forged from three pure metals and the Phantom Hourglass itself, this blade is the one weapon that can wound the soul-stealing Bellum and his phantoms.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/a0/PH_Phantom_Sword_Model.png"},{"name":"Wind Waker","rarity":"epic","id":"wind-waker","subtitle":"Baton","details":"A white conductor's baton passed down on the Great Sea, it directs the winds in time signatures and wakes sleeping sages with its sacred melodies.","image":"https://cdn.wikimg.net/en/zeldawiki/images/d/de/TWWHD_Wind_Waker_Artwork.png"},{"name":"Hookshot","rarity":"epic","id":"hookshot","subtitle":"Item","details":"A spring-loaded chain with a piercing tip, it latches onto torches, targets and wood, then yanks its user straight across pits and up onto high ledges.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/9d/OoT3D_Hookshot_Model.png"},{"name":"Bow of Light","rarity":"epic","id":"bow-of-light","subtitle":"Bow","details":"A sacred bow of pure light, wielded by Princess Zelda against Ganondorf from horseback and by Link against the demon king Malladus in the final battle.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/45/ST_Bow_of_Light_Artwork.png"},{"name":"Harp of Ages","rarity":"epic","id":"harp-of-ages","subtitle":"Instrument","details":"The oracle Nayru's harp, its Tune of Echoes, Currents and Ages opens time portals and carries its player between Labrynna's past and present at will.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/72/OoA_Harp_of_Ages_Artwork.png"},{"name":"Lokomo Sword","rarity":"epic","id":"lokomo-sword","subtitle":"Sword","details":"Entrusted to Link by the sage Anjean, this Spirit Tracks blade replaces his recruit's sword once the Tower of Spirits demands a worthier weapon of him.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/c9/ST_Lokomo_Sword_Artwork.png"},{"name":"Clawshot","rarity":"rare","id":"clawshot","subtitle":"Item","details":"A long chain ending in three gripping claws, it fires at vines, grates and targets; a second one lets its user cross entire ceilings hand over hand.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/f/fd/TP_Clawshot_Render.png/320px-TP_Clawshot_Render.png"},{"name":"Rod of Seasons","rarity":"rare","id":"rod-of-seasons","subtitle":"Rod","details":"Standing on a tree stump and swinging this rod cycles Holodrum through spring, summer, autumn and winter, draining lakes and piling up snowdrifts.","image":"https://cdn.wikimg.net/en/zeldawiki/images/e/ed/OoS_Rod_of_Seasons_Artwork.png"},{"name":"Picori Blade","rarity":"rare","id":"picori-blade","subtitle":"Sword","details":"A sacred sword gifted by the tiny Picori and shattered by Vaati, it is reforged with the four elements into the blade that becomes the Four Sword.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/7d/TMC_Picori_Blade_Sprite.png"},{"name":"Great Fairy's Sword","rarity":"rare","id":"great-fairys-sword","subtitle":"Sword","details":"Termina's strongest blade, patterned with black roses and gifted by the Great Fairy of Ikana after every stray fairy of Stone Tower Temple is rescued.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/1d/MM3D_Great_Fairy%27s_Sword_Model.png"},{"name":"Gilded Sword","rarity":"rare","id":"gilded-sword","subtitle":"Sword","details":"The fragile Razor Sword reforged at the Mountain Smithy with Gold Dust won at the Goron races, gaining a blade that never dulls across three full days.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/92/MM3D_Gilded_Sword_Model.png"},{"name":"Magic Mirror","rarity":"rare","id":"magic-mirror","subtitle":"Item","details":"Found in the Death Mountain of another world, this mirror warps its holder from the Dark World back to the exact matching spot in the Light World.","image":"https://cdn.wikimg.net/en/zeldawiki/images/0/03/ALttP_Magic_Mirror_Artwork.png"},{"name":"Moon Pearl","rarity":"rare","id":"moon-pearl","subtitle":"Item","details":"A treasure of the Tower of Hera, this pearl anchors its bearer's true shape, keeping him a boy instead of a bunny while he walks the Dark World.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/70/ALttP_Moon_Pearl_Artwork.png"},{"name":"Sheikah Slate","rarity":"rare","id":"sheikah-slate","subtitle":"Item","details":"An ancient Sheikah tablet that maps Hyrule, moves the world with runes like Magnesis and Stasis, and awakens from a hundred-year slumber with its hero.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/7d/BotW_Sheikah_Slate_Artwork.png"},{"name":"Purah Pad","rarity":"rare","id":"purah-pad","subtitle":"Item","details":"The Sheikah Slate's hand-built successor, this tablet pairs with the hero's new arm to offer Ultrahand, Fuse, Ascend, Recall and a full-sky map sensor.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/84/TotK_Purah_Pad_Model.png/320px-TotK_Purah_Pad_Model.png"},{"name":"Deku Mask","rarity":"rare","id":"deku-mask","subtitle":"Mask","details":"Carved from the spirit of the Deku Butler's lost son, this mask makes its wearer a Deku Scrub who spins, hops on water and glides from Deku Flowers.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/55/MM_Deku_Mask_Render.png"},{"name":"Goron Mask","rarity":"rare","id":"goron-mask","subtitle":"Mask","details":"Holding the spirit of the hero Darmani, this mask grants a Goron's body: rolling at speed, punching through rock and pounding the ground with great force.","image":"https://cdn.wikimg.net/en/zeldawiki/images/d/d2/MM3D_Goron_Mask_Render.png"},{"name":"Zora Mask","rarity":"rare","id":"zora-mask","subtitle":"Mask","details":"Holding the spirit of guitarist Mikau, this mask grants a Zora's body: swimming like a dolphin, breathing underwater and throwing boomerang-like fins.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/cd/MM3D_Zora_Mask_Render.png"},{"name":"Bunny Hood","rarity":"rare","id":"bunny-hood","subtitle":"Mask","details":"A simple hood with tall ears that sharpens the senses and makes its wearer run noticeably faster, a favourite of Termina's ever-hurrying postman too.","image":"https://cdn.wikimg.net/en/zeldawiki/images/e/e5/MM3D_Bunny_Hood_Render.png"},{"name":"Hero's Bow","rarity":"rare","id":"heros-bow","subtitle":"Bow","details":"The dungeon bow handed down through the Tower of the Gods, Gerudo training grounds and Twilight Hyrule, it fells distant switches and flying foes alike.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/1d/MM_Hero%27s_Bow_Render.png"},{"name":"Boomerang","rarity":"uncommon","id":"boomerang","subtitle":"Weapon","details":"In the hero's kit since the first quest of 1986, it stuns enemies mid-charge and fetches far-off rupees, hearts and keys straight back to the hand.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/60/ALttP_Boomerang_Artwork.png"},{"name":"Bombs","rarity":"uncommon","id":"bombs","subtitle":"Weapon","details":"Carried in a dedicated bag in nearly every quest, they crack walls, floors and armoured shells, and can be bowled, thrown, or set down as timed traps.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/1f/ALttP_Bomb_Artwork.png"},{"name":"Megaton Hammer","rarity":"uncommon","id":"megaton-hammer","subtitle":"Weapon","details":"A Goron-forged hammer from the Fire Temple, heavy enough to smash rusted switches, flatten stakes and knock the fire dragon Volvagia senseless twice.","image":"https://cdn.wikimg.net/en/zeldawiki/images/b/be/OoT3D_Megaton_Hammer_Artwork.png"},{"name":"Iron Boots","rarity":"uncommon","id":"iron-boots","subtitle":"Boots","details":"So heavy they sink their wearer to lakebeds and pin him against gale-force winds, yet light enough on magnetic ceilings to walk them upside down.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/a7/OoT_Iron_Boots_Render.png"},{"name":"Lens of Truth","rarity":"uncommon","id":"lens-of-truth","subtitle":"Item","details":"A Sheikah relic shaped like an eye, it burns magic to reveal invisible platforms, false walls and hidden chests that the naked eye simply cannot see.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/54/OoT_Lens_of_Truth_Render.png"},{"name":"Mask of Truth","rarity":"uncommon","id":"mask-of-truth","subtitle":"Mask","details":"Won by trading masks through the Happy Mask Shop's whole chain, this face lets its wearer hear the whispered secrets of Gossip Stones across the land.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/64/OoT_Mask_of_Truth_Render.png"},{"name":"Deku Leaf","rarity":"uncommon","id":"deku-leaf","subtitle":"Item","details":"Plucked in the Forest Haven, this giant leaf blasts enemies back with a gust of wind, then opens like a sail to glide its holder across wide sea gaps.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/4e/TWWHD_Deku_Leaf_Artwork.png"},{"name":"Fire Arrows","rarity":"uncommon","id":"fire-arrows","subtitle":"Weapon","details":"Arrows wreathed in flame, granted at Lake Hylia, they melt ice blocks, light distant torches and set whole packs of enemies ablaze from a safe range.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/95/OoT_Fire_Arrow_Render.png"},{"name":"Ice Arrows","rarity":"uncommon","id":"ice-arrows","subtitle":"Weapon","details":"Arrows chilled with deep frost, they freeze enemies solid into stepping blocks and cool the hottest waters, from pirate fortresses to Great Bay Temple.","image":"https://cdn.wikimg.net/en/zeldawiki/images/8/8a/OoT_Ice_Arrow_Render.png"},{"name":"Empty Bottle","rarity":"uncommon","id":"empty-bottle","subtitle":"Item","details":"The most versatile container in any quest, a single bottle can hold potions, milk, fairies, spring water, bugs, fish, and even a bottled Poe's ghost.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/fc/OoT_Empty_Bottle_Render.png"},{"name":"Zora Tunic","rarity":"uncommon","id":"zora-tunic","subtitle":"Armor","details":"Woven by King Zora from special fibres, this blue tunic lets its wearer breathe deep underwater, opening lakebed temples to a boy from the forest home.","image":"https://cdn.wikimg.net/en/zeldawiki/images/e/e3/OoT_Zora_Tunic_Render.png"},{"name":"Goron Tunic","rarity":"uncommon","id":"goron-tunic","subtitle":"Armor","details":"A heat-proof red tunic spun from durable fibres, it lets its wearer stand inside a volcano's crater and walk through the Fire Temple unburned at all.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/1f/OoT_Goron_Tunic_Render.png"},{"name":"Magic Armor","rarity":"uncommon","id":"magic-armor","subtitle":"Armor","details":"Sold by the Malo Mart empire, this gleaming armor makes its wearer invincible by burning rupees with every blow he takes, chiming as the purse empties.","image":"assets/sets/compress/zelda-additions__magic-armor.webp"},{"name":"Roc's Feather","rarity":"uncommon","id":"rocs-feather","subtitle":"Item","details":"Named for the great Roc, this feather gave the hero his first true jump, letting him hop pits, dodge rolling boulders and ride gusts in Koholint's dream.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/18/LA_Roc%27s_Feather_Artwork.png"},{"name":"Pegasus Boots","rarity":"uncommon","id":"pegasus-boots","subtitle":"Boots","details":"Charging in these boots builds a headlong dash that shakes loose books, apples and rupees from trees, and skewers enemies too slow to step aside.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/97/ALttP_Pegasus_Shoes_Artwork.png"},{"name":"Gust Jar","rarity":"uncommon","id":"gust-jar","subtitle":"Item","details":"This Minish-era jar inhales enemies, dust and mushrooms with a roaring vacuum, then blasts them out again in a gust strong enough to ride across water.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/ff/TMC_Gust_Jar_Artwork.png"},{"name":"Mole Mitts","rarity":"uncommon","id":"mole-mitts","subtitle":"Item","details":"Digging claws that tunnel through soft earth, sand and even cloud tops, unearthing rupees, hearts and secret passages hidden beneath the surface soil.","image":"https://www.zeldadungeon.net/wiki/images/2/21/Mole_Mitt_-_TMC_art.png"},{"name":"Magnetic Gloves","rarity":"uncommon","id":"magnetic-gloves","subtitle":"Item","details":"These gloves flip magnetic polarity with a wave, pulling iron orbs and masked enemies close or hurling them away across pits and puzzle-room gaps.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/c3/OoS_Magnetic_Glove_Artwork.png"},{"name":"Grappling Hook","rarity":"uncommon","id":"grappling-hook","subtitle":"Item","details":"A rope with a clawed hook from the Forsaken Fortress, it swings its user across chasms and snatches treasure straight out of an enemy's pockets mid-fight.","image":"https://cdn.wikimg.net/en/zeldawiki/images/3/35/TWWHD_Grappling_Hook_Artwork.png"},{"name":"Magnesis Rune","rarity":"uncommon","id":"magnesis-rune","subtitle":"Rune","details":"A Sheikah Slate rune that wraps metal in a red magnetic glow, lifting gates, bridges and treasure chests and swinging them freely through the open air.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/11/BotW_Magnesis_Icon.png"},{"name":"Kokiri's Emerald","rarity":"uncommon","id":"kokiris-emerald","subtitle":"Stone","details":"The Spiritual Stone of the Forest, a green gem entrusted to the Great Deku Tree and carried by his Kokiri children until a fairy-guided boy claims it.","image":"assets/sets/compress/zelda-additions__kokiris-emerald.webp"},{"name":"Goron's Ruby","rarity":"uncommon","id":"gorons-ruby","subtitle":"Stone","details":"The Spiritual Stone of Fire, a red gem treasured by Darunia and the Gorons of Death Mountain as the sign of their sworn brotherhood with Hyrule's king.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/7d/OoT_Spiritual_Stone_of_Fire_Artwork.png"},{"name":"Zora's Sapphire","rarity":"uncommon","id":"zoras-sapphire","subtitle":"Stone","details":"The Spiritual Stone of Water, a blue gem Princess Ruto calls her mother's stone and offers as an engagement gift to the boy who rescues her from Jabu-Jabu.","image":"assets/sets/compress/zelda-additions__zoras-sapphire.webp"},{"name":"Sage Medallions","rarity":"uncommon","id":"sage-medallions","subtitle":"Medallion","details":"Six medallions granted one by one as the Sages of Forest, Fire, Water, Shadow, Spirit and Light awaken, each adding its power to the hero's growing quest.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/ae/OoT3D_Medallions_Model.png"},{"name":"Wooden Sword","rarity":"common","id":"wooden-sword","subtitle":"Sword","details":"An old man's gift in a cave beneath Hyrule, offered with the words every player remembers: it is dangerous to go alone, so take this very first blade.","image":"assets/sets/compress/zelda-additions__wooden-sword.webp"},{"name":"Kokiri Sword","rarity":"common","id":"kokiri-sword","subtitle":"Sword","details":"A treasure of the Kokiri hidden in a forest training ground, this short blade is the first sword its forest-born hero ever holds in Ocarina of Time.","image":"https://cdn.wikimg.net/en/zeldawiki/images/8/8d/OoT_Kokiri_Sword_Render.png"},{"name":"Ordon Sword","rarity":"common","id":"ordon-sword","subtitle":"Sword","details":"Forged by the swordsman Rusl in Ordon Village as a gift for the royal family, this blade is carried toward Hyrule Castle but claimed by its hero first.","image":"assets/sets/compress/zelda-additions__ordon-sword.webp"},{"name":"Deku Shield","rarity":"common","id":"deku-shield","subtitle":"Shield","details":"Carved from the bark of the Great Deku Tree and sold in the Kokiri shop, this wooden shield blocks Deku nuts well but burns away in a moment of fire.","image":"https://cdn.wikimg.net/en/zeldawiki/images/b/b7/OoT_Deku_Shield_Render.png"},{"name":"Wooden Shield","rarity":"common","id":"wooden-shield","subtitle":"Shield","details":"The plain starter shield of the earliest quests, cheap and light in the hand, though a hungry Like Like can swallow it whole if its owner is careless.","image":"https://cdn.wikimg.net/en/zeldawiki/images/2/2f/SS_Wooden_Shield_Model.png"},{"name":"Lantern","rarity":"common","id":"lantern","subtitle":"Item","details":"An oil lamp that lights pitch-dark rooms, melts ice, and burns away brush in its path, carried through dungeons from Hyrule's castles to dark palaces.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/ff/ALttP_Lantern_Artwork.png"},{"name":"Candle","rarity":"common","id":"candle","subtitle":"Item","details":"The first quest's simple flame, sold in blue and upgraded to red, it lights black rooms one screen at a time and burns bushes hiding secret stairways.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/68/TLoZ_Blue_Candle_Artwork.png"},{"name":"Raft","rarity":"common","id":"raft","subtitle":"Item","details":"A small wooden raft that launches only from docks, it ferries its rider across open water to island dungeons, lake shrines and far dungeon entrances.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/a4/TLoZ_Raft_Artwork.png"},{"name":"Stepladder","rarity":"common","id":"stepladder","subtitle":"Item","details":"A humble ladder from the first dungeons that bridges exactly one gap of water, lava or pit, letting its bearer walk straight over without ever falling.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/53/TLoZ_Stepladder_Artwork.png"},{"name":"Slingshot","rarity":"common","id":"slingshot","subtitle":"Weapon","details":"A forked stick and elastic band that fires Deku Seeds, the young hero's first ranged weapon, used from the Deku Tree's webs to Skyloft's pumpkin patch.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/60/OoT_Fairy_Slingshot_Render.png"},{"name":"Deku Nuts","rarity":"common","id":"deku-nuts","subtitle":"Item","details":"Harvested from defeated Deku Babas, these nuts burst in a blinding flash when thrown, stunning whole rooms of enemies long enough to strike or escape.","image":"https://cdn.wikimg.net/en/zeldawiki/images/8/8e/OoT_Deku_Nut_Render.png"},{"name":"Deku Stick","rarity":"common","id":"deku-stick","subtitle":"Weapon","details":"A long branch snapped from a Deku Baba, it serves as a first reach weapon, a carryable torch for lighting braziers, and kindling once it burns through.","image":"https://cdn.wikimg.net/en/zeldawiki/images/3/3d/OoT_Deku_Stick_Render.png"},{"name":"Red Potion","rarity":"common","id":"red-potion","subtitle":"Potion","details":"The classic bottled tonic of potion shops everywhere, a single gulp restores the hero's hearts, making it the first purchase before any hard dungeon run.","image":"https://cdn.wikimg.net/en/zeldawiki/images/2/22/OoT_Red_Potion_Render.png"},{"name":"Blue Potion","rarity":"common","id":"blue-potion","subtitle":"Potion","details":"Brewed from mushroom scents or Chu Jelly, this richer tonic restores both hearts and magic at once, saving a hero caught far from any friendly shop.","image":"https://cdn.wikimg.net/en/zeldawiki/images/d/de/OoT_Blue_Potion_Render.png"},{"name":"Lon Lon Milk","rarity":"common","id":"lon-lon-milk","subtitle":"Food","details":"Bottled at Talon's ranch and sold with a cheery tune, each bottle holds two helpings of milk that restore hearts sip by sip on a long road across Hyrule.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/92/OoT3D_Lon_Lon_Milk_Model.png"},{"name":"Chateau Romani","rarity":"common","id":"chateau-romani","subtitle":"Food","details":"A vintage reserve milk from Romani Ranch, so rich that one bottle grants endless magic for all three days of Termina's carnival, at a steep 200 rupees.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/c2/MM_Chateau_Romani_Model.png"},{"name":"Bait","rarity":"common","id":"bait","subtitle":"Food","details":"A lump of food sold in the first quest's shops, it lures a starving Goriya away from a doorway and can distract hungry enemies long enough to slip by.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/71/TLoZ_Food_Artwork.png"},{"name":"Compass","rarity":"common","id":"compass","subtitle":"Item","details":"Hidden in every dungeon's chests, this compass marks the boss room, treasure chests and the hero's own position on maps drawn one chamber at a time.","image":"https://cdn.wikimg.net/en/zeldawiki/images/0/06/TLoZ_Compass_Artwork.png"},{"name":"Small Key","rarity":"common","id":"small-key","subtitle":"Key","details":"A single-use key hidden in chests or dropped by beaten enemies, it opens exactly one locked door in its dungeon and then vanishes from the pouch for good.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/52/ALttP_Small_Key_Artwork.png"},{"name":"Big Key","rarity":"common","id":"big-key","subtitle":"Key","details":"An ornate, oversized key guarded deep in each dungeon, sometimes by a miniboss, it opens the nightmare door behind which the dungeon's great evil waits.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/f0/ALttP_Big_Key_Artwork.png"},{"name":"Heart Container","rarity":"common","id":"heart-container","subtitle":"Item","details":"Left behind by every defeated dungeon boss, this full heart permanently extends the hero's life, the surest reward at the end of a long dangerous crawl.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/f4/OoT_Heart_Container_Render.png"},{"name":"Piece of Heart","rarity":"common","id":"piece-of-heart","subtitle":"Item","details":"A quarter of a heart hidden in caves, games, races and side quests across the world; collect four of them and they join into a new full Heart Container.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/a7/OoT_Piece_of_Heart_Render.png"},{"name":"Telescope","rarity":"common","id":"telescope","subtitle":"Item","details":"His younger sister Aryll's prized spyglass, lent for one birthday and kept for a quest, it first spots the Helmaroc King over the Great Sea from Outset.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/44/TWWHD_Telescope_Artwork.png"},{"name":"Picto Box","rarity":"common","id":"picto-box","subtitle":"Item","details":"A camera that captures pictographs in black and white, later colour, used for Windfall's shop, Termina's swamp contest and a gallery of carved figures.","image":"https://cdn.wikimg.net/en/zeldawiki/images/8/83/TWWHD_Picto_Box_Artwork.png"},{"name":"Fishing Rod","rarity":"common","id":"fishing-rod","subtitle":"Item","details":"An angler's rod for ponds, grottos and open sea, it lands ordinary fish, sinking lures, empty bottles, and in one era a piece of heart from the deep.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/f0/TPHD_Fishing_Rod_Artwork.png"},{"name":"Bug Net","rarity":"common","id":"bug-net","subtitle":"Item","details":"A simple net for sweeping up fairies, bees, bugs and butterflies to stock in bottles, carried from the palaces of Hyrule to the skies above the clouds.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/f9/ALttP_Bug_Catching_Net_Artwork.png"},{"name":"Bombchu","rarity":"common","id":"bombchu","subtitle":"Weapon","details":"A mouse-shaped bomb that winds up and scurries along floors, up walls and across ceilings before exploding, built for targets no thrown bomb can reach.","image":"https://cdn.wikimg.net/en/zeldawiki/images/c/c2/OoT_Bombchu_Render.png"},{"name":"Hyoi Pear","rarity":"common","id":"hyoi-pear","subtitle":"Item","details":"A pear-shaped fruit of the Great Sea that seagulls cannot resist; set one down and its eater's flight can be steered to switches no hero can reach alone.","image":"https://cdn.wikimg.net/en/zeldawiki/images/2/27/TWWHD_Hyoi_Pear_Artwork.png"},{"name":"Beetle","rarity":"common","id":"beetle","subtitle":"Item","details":"A mechanical beetle that launches from the hero's hand to scout ahead, snip threads, strike distant switches and ferry small items back through the air.","image":"assets/sets/compress/zelda-additions__beetle.webp"},{"name":"Mighty Bananas","rarity":"common","id":"mighty-bananas","subtitle":"Food","details":"Grown in the Faron rainforest and hoarded by the Yiga Clan, these bananas boost attack power when cooked and can bait a banana-obsessed foe off his post.","image":"https://cdn.wikimg.net/en/zeldawiki/images/0/0b/BotW_Mighty_Bananas_Model.png"},{"name":"Ocarina of Time","rarity":"chase","id":"ocarina-of-time-game","subtitle":"Game","details":"The 1998 Nintendo 64 landmark that moved the series into 3D, letting players cross seven years of Hyrule's fate with a single ocarina melody.","image":"https://cdn.wikimg.net/en/zeldawiki/images/4/48/OoT_NA_Box.jpg"},{"name":"Breath of the Wild","rarity":"chase","id":"breath-of-the-wild","subtitle":"Game","details":"The 2017 open-world reinvention for Switch and Wii U, where Link wakes after a century to a ruined Hyrule he may cross in any direction at all.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c7/BotW_NA_Switch_Box_Art.png/320px-BotW_NA_Switch_Box_Art.png"},{"name":"A Link to the Past","rarity":"legendary","id":"a-link-to-the-past","subtitle":"Game","details":"The 1991 Super Nintendo classic that split Hyrule between a Light World and a Dark World, a mirror structure the whole series keeps returning to.","image":"https://upload.wikimedia.org/wikipedia/en/2/21/The_Legend_of_Zelda_A_Link_to_the_Past_SNES_Game_Cover.jpg"},{"name":"Majora's Mask","rarity":"legendary","id":"majoras-mask-game","subtitle":"Game","details":"The 2000 Nintendo 64 sequel set in Termina, where the moon falls in three looping days and transformation masks let Link live other lives.","image":"assets/sets/compress/zelda-additions__majoras-mask-game.webp"},{"name":"Tears of the Kingdom","rarity":"legendary","id":"tears-of-the-kingdom","subtitle":"Game","details":"The 2023 Switch sequel that opened Hyrule's skies and Depths, built around Ultrahand creations fused together from the world's own scattered parts.","image":"assets/sets/compress/zelda-additions__tears-of-the-kingdom.webp"},{"name":"The Wind Waker","rarity":"legendary","id":"the-wind-waker","subtitle":"Game","details":"The 2002 GameCube voyage across a flooded Hyrule, where Link sails the Great Sea with a talking boat and conducts the winds with a baton.","image":"assets/sets/compress/zelda-additions__the-wind-waker.webp"},{"name":"The Legend of Zelda","rarity":"epic","id":"the-legend-of-zelda","subtitle":"Game","details":"The 1986 NES original that began the series, dropping players into Hyrule with no map or directions and a cave elder's famous warning.","image":"assets/sets/compress/zelda-additions__the-legend-of-zelda.webp"},{"name":"Twilight Princess","rarity":"epic","id":"twilight-princess","subtitle":"Game","details":"The 2006 GameCube and Wii adventure in which Link crosses a Hyrule drowned in twilight, cursed to wander part of the journey as a wolf.","image":"https://cdn.wikimg.net/en/zeldawiki/images/5/57/TP_NA_Wii_Box_Art.jpg"},{"name":"Link's Awakening","rarity":"epic","id":"links-awakening","subtitle":"Game","details":"The 1993 Game Boy odyssey to Koholint Island, a strange shore of talking animals and borrowed faces that exists only inside the Wind Fish's dream.","image":"assets/sets/compress/zelda-additions__links-awakening.webp"},{"name":"A Link Between Worlds","rarity":"epic","id":"a-link-between-worlds","subtitle":"Game","details":"The 2013 Nintendo 3DS return to A Link to the Past's Hyrule, built around Link flattening into a living painting to slip along walls and cracks.","image":"assets/sets/compress/zelda-additions__a-link-between-worlds.webp"},{"name":"Skyward Sword","rarity":"rare","id":"skyward-sword","subtitle":"Game","details":"The 2011 Wii prequel telling the series' earliest tale, where Link dives from the floating isle of Skyloft to a surface world no one remembers.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/18/SS_NA_Box_Art.png/320px-SS_NA_Box_Art.png"},{"name":"The Minish Cap","rarity":"rare","id":"the-minish-cap","subtitle":"Game","details":"The 2004 Game Boy Advance adventure where a talking cap shrinks Link to Picori size, opening a miniature world hidden inside Hyrule's everyday one.","image":"assets/sets/compress/zelda-additions__the-minish-cap.webp"},{"name":"Echoes of Wisdom","rarity":"rare","id":"echoes-of-wisdom","subtitle":"Game","details":"The 2024 Switch adventure starring Princess Zelda herself, who saves Hyrule with the Tri Rod, summoning echoes of objects and monsters alike.","image":"assets/sets/compress/zelda-additions__echoes-of-wisdom.webp"},{"name":"Oracle of Seasons","rarity":"rare","id":"oracle-of-seasons","subtitle":"Game","details":"The 2001 Game Boy Color quest through Holodrum, where the Rod of Seasons turns winter to spring on a stump and reshapes the land itself.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/aa/OoS_NA_Box_Art.jpg"},{"name":"Oracle of Ages","rarity":"rare","id":"oracle-of-ages","subtitle":"Game","details":"The 2001 Game Boy Color quest through Labrynna, where the Harp of Ages carries Link between a kingdom's past and its present, centuries apart.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/98/OoA_NA_Box_Art.jpg"},{"name":"Zelda II: The Adventure of Link","rarity":"uncommon","id":"zelda-ii-the-adventure-of-link","subtitle":"Game","details":"The 1987 NES sequel that traded the top-down view for side-scrolling towns and palaces, and gave Link spells, lives and a shadow to fear.","image":"assets/sets/compress/zelda-additions__zelda-ii-the-adventure-of-link.webp"},{"name":"Phantom Hourglass","rarity":"uncommon","id":"phantom-hourglass","subtitle":"Game","details":"The 2007 Nintendo DS sequel to The Wind Waker, a stylus-drawn sea voyage built around the endlessly re-entered Temple of the Ocean King.","image":"assets/sets/compress/zelda-additions__phantom-hourglass.webp"},{"name":"Spirit Tracks","rarity":"uncommon","id":"spirit-tracks","subtitle":"Game","details":"The 2009 Nintendo DS adventure where Link drives a spirit train across New Hyrule while Princess Zelda rides beside him as a ghostly partner.","image":"assets/sets/compress/zelda-additions__spirit-tracks.webp"},{"name":"Four Swords Adventures","rarity":"uncommon","id":"four-swords-adventures","subtitle":"Game","details":"The 2004 GameCube quest built for four Links at once, played shoulder to shoulder with Game Boy Advances linked to the television screen.","image":"https://cdn.wikimg.net/en/zeldawiki/images/0/05/FSA_NA_Box_Art.jpg"},{"name":"Four Swords","rarity":"common","id":"four-swords","subtitle":"Game","details":"The 2002 Game Boy Advance multiplayer quest bundled with A Link to the Past, where up to four Links race through shrines on a single link cable.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/6/62/FS_Links_Artwork.png/320px-FS_Links_Artwork.png"},{"name":"Tri Force Heroes","rarity":"common","id":"tri-force-heroes","subtitle":"Game","details":"The 2015 Nintendo 3DS romp in the fashion-obsessed kingdom of Hytopia, where three Links stack into totems and outfits grant the abilities.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/9/98/TFH_NA_Box_Art.png/320px-TFH_NA_Box_Art.png"},{"name":"Zelda's Lullaby","rarity":"epic","id":"zeldas-lullaby","subtitle":"Song","details":"The royal family's melody, taught by Impa and played on the ocarina to prove a messenger's credentials before Hyrule's sealed places and signs.","image":"assets/sets/compress/zelda-additions__zeldas-lullaby.webp"},{"name":"Song of Time","rarity":"epic","id":"song-of-time","subtitle":"Song","details":"The ocarina melody at the heart of the Temple of Time: three notes that move blocks, open the Door of Time and rewind Termina's three days.","image":"assets/sets/compress/zelda-additions__song-of-time.webp"},{"name":"Ballad of the Goddess","rarity":"rare","id":"ballad-of-the-goddess","subtitle":"Song","details":"Skyloft's ancient hymn to the goddess Hylia, sung by Zelda at the Wing Ceremony; its notes played in reverse form the royal Zelda's Lullaby.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/1d/SS_Zelda_Artwork.png/512px-SS_Zelda_Artwork.png"},{"name":"Song of Healing","rarity":"rare","id":"song-of-healing","subtitle":"Song","details":"The piano melody of Majora's Mask that soothes tormented souls, sealing their regrets into masks the living can wear and finally rest from.","image":"assets/sets/compress/zelda-additions__song-of-healing.webp"},{"name":"Epona's Song","rarity":"rare","id":"eponas-song","subtitle":"Song","details":"The gentle ranch melody Malon teaches young Link, her mother's song passed down; wherever it sounds across the fields, Epona comes running.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/28/OoT_Malon_Artwork.png/512px-OoT_Malon_Artwork.png"},{"name":"Song of Storms","rarity":"rare","id":"song-of-storms","subtitle":"Song","details":"The windmill man's looping, furious tune, learned from a paradox and played to summon rain, drain wells and spin Guru-Guru's mill forever.","image":"https://cdn.wikimg.net/en/zeldawiki/images/d/d3/OoT_Song_of_Storms.png"},{"name":"Goron","rarity":"rare","id":"goron","subtitle":"Race","details":"Hyrule's rock-eating mountain folk: immensely strong, warm-hearted and built to roll, curled into boulders that thunder down Death Mountain.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/7c/OoT_Goron_Artwork.png/512px-OoT_Goron_Artwork.png"},{"name":"Sun's Song","rarity":"uncommon","id":"suns-song","subtitle":"Song","details":"A melody composed by the royal family's Composer Brothers, studied in their grave; it turns day to night and freezes the undead where they stand.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/a8/OoT_Royal_Family%27s_Tomb.png/320px-OoT_Royal_Family%27s_Tomb.png"},{"name":"Saria's Song","rarity":"uncommon","id":"sarias-song","subtitle":"Song","details":"The Kokiri sage's cheerful forest tune, a promise that friendship carries anywhere; even the Goron patriarch Darunia cannot resist dancing to it.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/0/0f/OoT_Saria_Artwork.png/512px-OoT_Saria_Artwork.png"},{"name":"Zora","rarity":"uncommon","id":"zora","subtitle":"Race","details":"Hyrule's aquatic people of river, lake and sea: elegant fish-like folk whose scales let them breathe deep and whose fins slice the deepest water.","image":"assets/sets/compress/zelda-additions__zora.webp"},{"name":"Gerudo","rarity":"uncommon","id":"gerudo","subtitle":"Race","details":"The desert warriors of Hyrule's west, a people of women among whom a single man is born once a century, destined by custom to be their king.","image":"https://cdn.wikimg.net/en/zeldawiki/images/0/02/OoT_Gerudo_Guard_Artwork.png"},{"name":"Sheikah","rarity":"uncommon","id":"sheikah","subtitle":"Race","details":"The shadow tribe sworn for ten thousand years to Hyrule's royal family, keepers of ancient technology who serve from darkness and near secrecy.","image":"assets/sets/compress/zelda-additions__sheikah.webp"},{"name":"Rito","rarity":"uncommon","id":"rito","subtitle":"Race","details":"The winged bird folk of the Hebra skies and Dragon Roost, who earn true flight at Valoo's shrine and carry Hyrule's mail across its widest distances.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/8f/BotW_Rito.png/320px-BotW_Rito.png"},{"name":"The Champions","rarity":"uncommon","id":"the-champions","subtitle":"Group","details":"Daruk, Mipha, Revali and Urbosa: the four pilots chosen from Hyrule's peoples to command the Divine Beasts against the Calamity's return.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/1/17/BotW_Champions_Artwork.png/320px-BotW_Champions_Artwork.png"},{"name":"The Seven Sages","rarity":"uncommon","id":"the-seven-sages","subtitle":"Group","details":"The awakened sages of forest, fire, water, shadow, spirit, light and time, whose combined power seals great evil away from the world it threatens.","image":"https://cdn.wikimg.net/en/zeldawiki/images/2/20/OoT3D_Chamber_of_Sages.png"},{"name":"The Golden Goddesses","rarity":"uncommon","id":"the-golden-goddesses","subtitle":"Lore","details":"Din, Nayru and Farore, the three goddesses who shaped the world from chaos, made its laws and life, then departed, leaving the Triforce behind.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/3/3d/ALttP_Goddesses_Artwork.png/320px-ALttP_Goddesses_Artwork.png"},{"name":"The Sacred Realm","rarity":"uncommon","id":"the-sacred-realm","subtitle":"Lore","details":"The mirrored holy land where the Triforce rests, a golden place that reshapes itself around the heart of whoever enters and claims its power.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/10/OoT_Sacred_Realm.png"},{"name":"Minuet of Forest","rarity":"common","id":"minuet-of-forest","subtitle":"Song","details":"The first warp melody Sheik teaches at the Sacred Forest Meadow, carrying the ocarina's player straight back to the Forest Temple's threshold.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/75/OoT_Sacred_Forest_Meadow.png/512px-OoT_Sacred_Forest_Meadow.png"},{"name":"Bolero of Fire","rarity":"common","id":"bolero-of-fire","subtitle":"Song","details":"Sheik's warp melody of flame, taught above Death Mountain's crater to carry Link directly to the Fire Temple burning in the volcano's heart.","image":"https://cdn.wikimg.net/en/zeldawiki/images/f/fc/OoT_Bolero_of_Fire.png"},{"name":"Serenade of Water","rarity":"common","id":"serenade-of-water","subtitle":"Song","details":"Sheik's flowing warp melody, played to carry Link to Lake Hylia's shore, within sight of the Water Temple sunken beneath its island shrine.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/8e/OoT_Lake_Hylia.png/512px-OoT_Lake_Hylia.png"},{"name":"Requiem of Spirit","rarity":"common","id":"requiem-of-spirit","subtitle":"Song","details":"Sheik's haunting warp melody of the desert, carrying Link to the Desert Colossus and the Spirit Temple waiting beyond the haunted wasteland.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/e2/OoT_Desert_Colossus.png/512px-OoT_Desert_Colossus.png"},{"name":"Nocturne of Shadow","rarity":"common","id":"nocturne-of-shadow","subtitle":"Song","details":"Sheik's sombre warp melody, taught in Kakariko as darkness gathers, carrying Link to the graveyard and the Shadow Temple hidden beneath it.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/a/ab/OoT_Kakariko_Village.png/512px-OoT_Kakariko_Village.png"},{"name":"Prelude of Light","rarity":"common","id":"prelude-of-light","subtitle":"Song","details":"The last of Sheik's warp melodies, taught in the Temple of Time itself; its notes always lead the hero home to that sacred threshold again.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/9b/OoT_Temple_of_Time.png"},{"name":"Oath to Order","rarity":"common","id":"oath-to-order","subtitle":"Song","details":"The giants' summoning song, taught by the first freed giant beyond Woodfall and played atop Clock Tower to call all four guardians together.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/6a/MM3D_Clock_Tower.png"},{"name":"Song of Soaring","rarity":"common","id":"song-of-soaring","subtitle":"Song","details":"The melody the Soaring Stones carry across Termina, lifting Link on wings of song to the owl statues watching over each corner of the land.","image":"https://cdn.wikimg.net/en/zeldawiki/images/1/1d/MM_Owl_Statue_Model.png"},{"name":"Hylian","rarity":"common","id":"hylian","subtitle":"Race","details":"The pointed-eared people of Hyrule, founders of its kingdom and royal line, said to keep their long ears to hear the voices of the gods themselves.","image":"https://cdn.wikimg.net/en/zeldawiki/images/0/00/BotW_Hylian_Species.png"},{"name":"Kokiri","rarity":"common","id":"kokiri","subtitle":"Race","details":"The eternal children of Kokiri Forest, who never grow old, each paired for life with a fairy companion under the Great Deku Tree's protection.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/2/2b/OoT_Kokiri_Artwork.png/512px-OoT_Kokiri_Artwork.png"},{"name":"Deku","rarity":"common","id":"deku","subtitle":"Race","details":"Hyrule's plant folk of scrub, shrub and palace: merchants, mad scrubs and a whole royal court holding sway at the palace in Woodfall's swamp.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/8d/MM_Deku_Scrub_Artwork.png/512px-MM_Deku_Scrub_Artwork.png"},{"name":"Korok","rarity":"common","id":"korok","subtitle":"Race","details":"The leaf-masked forest spirits who took the Kokiri's place in later ages, hiding in plain sight across Hyrule and rewarding anyone who finds them.","image":"assets/sets/compress/zelda-additions__korok.webp"},{"name":"Minish","rarity":"common","id":"minish","subtitle":"Race","details":"The thumb-sized Picori, visible only to children, who hide Rupees, hearts and lucky fragments in Hyrule's grass for kind people to discover.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/6f/TMC_Minish_Concept_Artwork.png"},{"name":"Anouki","rarity":"common","id":"anouki","subtitle":"Race","details":"The antlered islanders of the frozen Isle of Frost, blunt, honest folk who judge strangers by their horns and settle arguments with pairing games.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/e/eb/PH_Anouki_Artwork.png/512px-PH_Anouki_Artwork.png"},{"name":"Twili","rarity":"common","id":"twili","subtitle":"Race","details":"The gentle shadow people of the Twilight Realm, descended from sorcerers banished long ago for reaching, too greedily, for the Sacred Realm.","image":"https://cdn.wikimg.net/en/zeldawiki/images/7/76/TP_Twili_Artwork.png"},{"name":"Zonai","rarity":"common","id":"zonai","subtitle":"Race","details":"The ancient, vanished builders of astonishing devices and floating ruins, whose technology and stonework still span Hyrule's skies and Depths.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/d/d8/TotK_Zonai.png/512px-TotK_Zonai.png"},{"name":"Oocca","rarity":"common","id":"oocca","subtitle":"Race","details":"The strange, small sky folk of the City in the Sky, said in Hylian legend to be closer to the gods than the Hylians, and older than their kingdom.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/60/TP_Ooccoo_Model.png"},{"name":"Wind's Requiem","rarity":"common","id":"winds-requiem","subtitle":"Song","details":"The first melody Link conducts with the Wind Waker baton, a three-beat requiem that turns the Great Sea's shifting winds to whatever course he sets.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/8/83/TWW_Wind_Shrine.png/320px-TWW_Wind_Shrine.png"},{"name":"The Four Giants","rarity":"common","id":"the-four-giants","subtitle":"Group","details":"Termina's four guardian gods, dwelling in Woodfall, Snowhead, Great Bay and Ikana, who sleep until the Oath to Order calls them to hold the moon.","image":"https://cdn.wikimg.net/en/zeldawiki/images/a/a3/SSBM_Four_Giants_Trophy_Model.png"},{"name":"Yiga Clan","rarity":"common","id":"yiga-clan","subtitle":"Group","details":"The Sheikah traitors who swore themselves to the Calamity's return: masters of disguise and ambush, devoted utterly to their beloved bananas.","image":"assets/sets/compress/zelda-additions__yiga-clan.webp"},{"name":"Tetra's Pirates","rarity":"common","id":"tetras-pirates","subtitle":"Group","details":"Tetra's loyal Great Sea crew: Gonzo, Senza, Nudge, Mako, Zuko and Niko, treasure hunters and sailors who comic-relief their way into every rescue.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/c/c6/TWW_Tetra%27s_Pirate_Crew_Artwork.png/512px-TWW_Tetra%27s_Pirate_Crew_Artwork.png"},{"name":"The Imprisoning War","rarity":"common","id":"the-imprisoning-war","subtitle":"Lore","details":"The war of A Link to the Past's backstory, when Ganon's evil poured from the Dark World and the Knights fell buying the Sages time to seal it.","image":"assets/sets/compress/zelda-additions__the-imprisoning-war.webp"},{"name":"The Great Flood","rarity":"common","id":"the-great-flood","subtitle":"Lore","details":"The deluge the gods sent when no hero appeared: Hyrule's people fled to the mountaintops, and its kingdom slept beneath an endless Great Sea.","image":"https://cdn.wikimg.net/en/zeldawiki/images/9/9e/TWW_Hyrule_Flooding.png"},{"name":"The Hero's Spirit","rarity":"common","id":"the-heros-spirit","subtitle":"Lore","details":"The undying spirit passed from hero to hero across Hyrule's ages, so that whenever darkness gathers, a chosen youth in green rises to meet it.","image":"assets/sets/compress/zelda-additions__the-heros-spirit.webp"},{"name":"The Curse of Demise","rarity":"common","id":"the-curse-of-demise","subtitle":"Lore","details":"The dying curse of the Demon King Demise, binding his hatred to be reborn forever against the blood of the goddess and the spirit of the hero.","image":"https://cdn.wikimg.net/en/zeldawiki/images/6/67/SS_Demise_Concept_Artwork.jpg"},{"name":"The Calamity","rarity":"common","id":"the-calamity","subtitle":"Lore","details":"Ganon's hatred given returning form, a malice so vast it poisoned Hyrule's guardians and Divine Beasts and left the kingdom a century of ruin.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/7/71/BotW_Calamity_Ganon_Tapestry.png/320px-BotW_Calamity_Ganon_Tapestry.png"},{"name":"The Blood Moon","rarity":"common","id":"the-blood-moon","subtitle":"Lore","details":"The crimson moon of Ganon's peak power, rising over Hyrule to breathe life back into every slain monster and undo the hero's hardest victories.","image":"https://cdn.wikimg.net/en/zeldawiki/images/thumb/b/bf/BotW_Blood_Moon.png/320px-BotW_Blood_Moon.png"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
